const express = require('express');

class Server {
  constructor() {
    this.handlers = new Map();
    this.resources = new Map();
    this.prompts = [];
    this.contextManager = null;
    this.app = express();
    this.app.use(express.json());

    this.app.get('/natural', (req, res) => {
      res.status(200).send('This endpoint expects a POST request with a JSON body containing a "text" field. Example: {"text": "Send 0.1 tokens to 0xRecipientAddress and generate a meme to celebrate with success saying Great Job"}');
    });

    this.app.post('/natural', async (req, res) => {
      const { text } = req.body;
      if (!text) {
        return res.status(400).json({ error: 'Missing "text" in request body' });
      }

      try {
        const { handler, params } = await this.processNaturalLanguage(text);
        if (!this.handlers.has(handler)) {
          return res.status(404).json({ error: `Handler for "${handler}" not found` });
        }

        const handlerFn = this.handlers.get(handler);
        const result = await handlerFn({ params });

        if (this.contextManager) {
          const contextResult = await this.contextManager({
            sessionId: 'default-session',
            action: handler,
          });
          result.context = contextResult;
        }

        res.json(result);
      } catch (error) {
        res.status(500).json({ error: `Failed to process request: ${error.message}` });
      }
    });

    this.app.post('/request', async (req, res) => {
      const { handler, params } = req.body;
      if (!this.handlers.has(handler)) {
        return res.status(404).json({ error: `Handler "${handler}" not found` });
      }
      try {
        const handlerFn = this.handlers.get(handler);
        const result = await handlerFn({ params });
        res.json(result);
      } catch (error) {
        res.status(500).json({ error: error.message });
      }
    });
  }

  setRequestHandler(name, handler) {
    console.log(`Handler set: ${name}`);
    this.handlers.set(name, handler);
  }

  setResource(name, resource) {
    console.log(`Resource set: ${name}`);
    this.resources.set(name, resource);
  }

  setPrompts(prompts) {
    console.log('Prompts set');
    this.prompts = prompts;
  }

  setContextManager(manager) {
    console.log('Context manager set');
    this.contextManager = manager;
  }

  async processNaturalLanguage(text) {
    const normalizedText = text.toLowerCase().trim();
    let matchedPrompt = null;
    let params = {};

    // First, try to match prompts based on their templates
    for (const prompt of this.prompts) {
      const templateWords = prompt.template.toLowerCase().split(/{|}/);
      const keywords = templateWords
        .filter(word => !word.includes(':') && word.trim())
        .map(word => word.trim())
        .filter(word => word.length > 0);

      // Check if most keywords are present in the normalized text (less strict matching)
      const keywordMatchCount = keywords.reduce((count, keyword) => {
        return count + (normalizedText.includes(keyword) ? 1 : 0);
      }, 0);
      const matchThreshold = Math.max(1, Math.floor(keywords.length * 0.7)); // Require 70% of keywords to match

      if (keywordMatchCount >= matchThreshold) {
        matchedPrompt = prompt;
        break;
      }
    }

    if (!matchedPrompt) {
      throw new Error('No matching prompt found for the request');
    }

    if (matchedPrompt.name === 'sendAndCelebrate') {
      const sendMatch = normalizedText.match(/send (\d*\.?\d+) tokens to (0x[a-f0-9]+)/);
      // Updated regex to match the new template: "generate a meme with template: {template} and text: {text}"
      const memeMatch = normalizedText.match(/generate a meme with template: ([a-z-]+) and text: ([a-zA-Z\s!]+)/);

      // Fallback to match the input format used in the request
      if (!memeMatch) {
        const fallbackMemeMatch = normalizedText.match(/generate a meme to celebrate with ([a-z-]+) saying ([a-zA-Z\s!]+)/);
        if (sendMatch && fallbackMemeMatch) {
          const template = fallbackMemeMatch[1] === 'success-kid' ? 'success' : fallbackMemeMatch[1];
          params = {
            send: { to: sendMatch[2], value: sendMatch[1] },
            meme: { template, text: fallbackMemeMatch[2] },
          };
          return {
            handler: 'sendAndCelebrate',
            params,
          };
        }
      }

      if (sendMatch && memeMatch) {
        const template = memeMatch[1] === 'success-kid' ? 'success' : memeMatch[1];
        params = {
          send: { to: sendMatch[2], value: sendMatch[1] },
          meme: { template, text: memeMatch[2] },
        };
        return {
          handler: 'sendAndCelebrate',
          params,
        };
      }
    } else if (matchedPrompt.name === 'deployAndTestContract') {
      const deployMatch = normalizedText.match(/deploy a.*contract with.*code ([a-zA-Z0-9]+)/);
      const callMatch = normalizedText.match(/call its function ([a-zA-Z0-9]+) with args (.*)/);

      if (deployMatch && callMatch) {
        params = {
          deploy: { contractCode: deployMatch[1] },
          call: { functionName: callMatch[1], args: callMatch[2].split(',').map(arg => arg.trim()) },
        };
        return {
          handler: 'deployAndTestContract',
          params,
        };
      }
    } else if (matchedPrompt.name === 'checkBalanceAndAnalyze') {
      const balanceMatch = normalizedText.match(/check balance of (0x[a-fA-F0-9]+)/);
      const analyzeMatch = normalizedText.match(/analyze with query (.*)/);

      if (balanceMatch && analyzeMatch) {
        params = {
          balance: { address: balanceMatch[1] },
          analytics: { query: analyzeMatch[1] },
        };
        return {
          handler: 'checkBalanceAndAnalyze',
          params,
        };
      }
    } else if (matchedPrompt.name === 'deployAndTrack') {
      const deployMatch = normalizedText.match(/deploy a.*contract with.*code ([a-zA-Z0-9]+)/);
      if (deployMatch) {
        params = {
          deploy: { contractCode: deployMatch[1] },
        };
        return {
          handler: 'deployAndTrack',
          params,
        };
      }
    } else if (matchedPrompt.name === 'createMemeCoin') {
      const memeCoinMatch = normalizedText.match(
        /create a meme coin called ([a-zA-Z0-9]+) with symbol ([a-zA-Z0-9]+) and initial supply (\d+)/
      );
      const memeMatch = normalizedText.match(/generate a meme with template ([a-z-]+) and text ([a-zA-Z\s!]+)/);

      if (memeCoinMatch && memeMatch) {
        const template = memeMatch[1] === 'success-kid' ? 'success' : memeMatch[1];
        params = {
          memeCoin: {
            name: memeCoinMatch[1],
            symbol: memeCoinMatch[2],
            supply: memeCoinMatch[3],
          },
          meme: {
            template,
            text: memeMatch[2],
          },
        };
        return {
          handler: 'createMemeCoin',
          params,
        };
      }
    }

    // Fallback checks
    if (normalizedText.includes('check balance') || normalizedText.includes('get wallet details')) {
      const addressMatch = normalizedText.match(/(0x[a-fA-F0-9]+)/);
      if (addressMatch) {
        return {
          handler: 'getBalance',
          params: { address: addressMatch[1] },
        };
      }
    } else if (normalizedText.includes('generate a meme')) {
      const memeMatch = normalizedText.match(/generate a meme.*with ([a-z-]+) saying ([a-zA-Z\s!]+)/);
      if (memeMatch) {
        const template = memeMatch[1] === 'success-kid' ? 'success' : memeMatch[1];
        return {
          handler: 'generateMeme',
          params: { template, text: memeMatch[2] },
        };
      }
    }

    throw new Error('Could not parse parameters from the request');
  }

  start() {
    console.log('Server started');
    this.app.listen(3000, () => {
      console.log('MCP Server listening on port 3000');
    });
  }
}

module.exports = { Server };